public function exportTrads() {

    /**
     * Export testi
     */
    $export = [];
    $result = $this->pdo->query("SELECT * FROM ".$this->arOptions["table_trad"]." ORDER BY group_code ASC, code ASC", PDO::FETCH_ASSOC);
    if ($result) :

        foreach ($result as $key => $rs): 

            unset($rs['date_update']);
            if(isset($rs['id'])) unset($rs['id']);

            $export[] = $rs;

        endforeach;
    endif;

    $written = file_put_contents($this->arOptions['lang_export_folder']."/trads.json", json_encode($export, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    if(!$written) {
        throw new Exception('Errore export traduzioni');
    }


    /**
     * Export link
     */
    $export = [];
    $result = $this->pdo->query("SELECT * FROM ".$this->arOptions["table_link"]." ORDER BY code ASC", PDO::FETCH_ASSOC);
    if ($result) :

        foreach ($result as $key => $rs): 

            unset($rs['date_update']);
            if(isset($rs['id'])) unset($rs['id']);
            if(isset($rs['type'])) unset($rs['type']);

            $export[] = $rs;

        endforeach;
    endif;

    $written = file_put_contents($this->arOptions['lang_export_folder']."/links.json", json_encode($export, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    if(!$written) {
        throw new Exception('Errore export link');
    }

